pages/order-confirmation:
{{#partial "head"}}
{{{ checkout.checkout_head }}}
{{{ stylesheet '/assets/css/optimized-checkout.css' }}}
{{ getFontsCollection }}

<script type="text/javascript">
    window.language = {{{langJson 'optimized_checkout'}}};
</script>

{{{head.scripts}}}

{{/partial}}

{{#partial "page"}}

<div class="container">
    <header class="checkoutHeader optimizedCheckout-header">
        <div class="checkoutHeader-content">
            <h1 class="is-srOnly">{{lang 'checkout.title'}}</h1>
            <h2 class="checkoutHeader-heading">
                <a class="checkoutHeader-link" href="{{urls.home}}">
                    {{#if checkout.header_image}}
                        <img alt="{{settings.store_logo.title}}" class="checkoutHeader-logo" id="logoImage" src="{{ checkout.header_image }}"/>
                    {{ else }}
                        <span class="header-logo-text">{{settings.store_logo.title}}</span>
                    {{/if}}
                </a>
            </h2>
        </div>
    </header>
    
    {{{ checkout.order_confirmation_content }}}
    
    {{{ footer.scripts }}}
</div>
{{/partial}}

{{> layout/empty}}
<div id="feedback-popup-overlay" style="display:none; position:fixed; top:0; left:0; width:100%; height:100%; background:rgba(0,0,0,0.6); z-index:999999;">
    <div id="feedback-popup-content" style="position:absolute; top:50%; left:50%; transform:translate(-50%,-50%); background:#fff; padding:30px; border-radius:8px; border-top:5px solid #e31b23; width:90%; max-width:500px; box-shadow:0 4px 15px rgba(0,0,0,0.3);">
        <h3 style="margin-top:0; color:#333; font-family:sans-serif;">Help us improve!</h3>
        <p style="color:#666; font-family:sans-serif;">How did you hear about us?</p>
        <div id="hubspot-form-container"></div>
        <button onclick="document.getElementById('feedback-popup-overlay').style.display='none'" style="margin-top:15px; background:#333; color:#fff; border:none; padding:8px 15px; border-radius:4px; cursor:pointer;">Close</button>
    </div>
</div>

<script charset="utf-8" type="text/javascript" src="//js.hsforms.net/forms/embed/v2.js"></script>
<script>
    window.addEventListener('load', function() {
        setTimeout(function(){
            document.getElementById('feedback-popup-overlay').style.display = 'block';
            hbspt.forms.create({
                portalId: "6036148",
                formId: "d36acbee-1249-4505-9592-8741d7a15545",
                region: "na1",
                target: '#hubspot-form-container'
            });
        }, 3000);
    });
</script>
